//! Protocol-level constants and magic numbers for the Kinetic network.
//!
//! These values define the immutable characteristics of the network (like the NSP
//! suffix, bootstrap nodes, and genesis time). Once compiled, they cannot be changed
//! without forking the network and creating a new node binary.

//! To customize these values for your own network deployment, modify `default_network.json`.
//! See `build.rs` for the code generation logic that builds this file.

// `network_constants.rs` is automatically generated by `build.rs`.
// Includes: NSP, NETWORK_ID, GOVERNANCE_MODEL, BOOTSTRAP_NODES, etc.
// ============================================================================
include!(concat!(env!("OUT_DIR"), "/network_constants.rs"));

/// The mathematically derived 32-byte cryptographic salt unique to this network's
/// combination of `NETWORK_ID` and Sovereign Governance `ROOT_PUBLIC_KEY`.
/// Used natively across the architecture to mathematically isolate networks.
#[cfg(not(test))]
pub const NETWORK_SALT: &[u8; 32] = &NETWORK_SALT_PROD;

/// The mathematical network salt for production, hex encoded.
#[cfg(not(test))]
pub const NETWORK_SALT_HEX: &str = NETWORK_SALT_HEX_PROD;

/// The mathematically derived 32-byte cryptographic salt for testing.
#[cfg(test)]
pub const NETWORK_SALT: &[u8; 32] = &NETWORK_SALT_TEST;

/// The mathematical network salt for testing, hex encoded.
#[cfg(test)]
pub const NETWORK_SALT_HEX: &str = NETWORK_SALT_HEX_TEST;

